import os

PYTHON_VERSION = '3.8'
PATH_TO_APPEND = '/path/to/whatever'

def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    python_cmd = f'python{python_version}'
    try:
        subprocess.check_output([python_cmd, '--version'], stderr=subprocess.STDOUT)
    except (subprocess.CalledProcessError, FileNotFoundError):
        raise FileNotFoundError(f"Python version {python_version} not found.")

    if path_to_append not in sys.path:
        sys.path.append(path_to_append)

    os.environ['PATH'] = f"{os.path.dirname(subprocess.check_output(['which', python_cmd]).decode().strip())}:{os.environ['PATH']}"

    return str(python_version)

